let operationBusy=TTI.busy;Object.defineProperty(TTI,'busy',{get(){return operationBusy;},set(value){operationBusy=Boolean(value);this.updateUndo?.();}});
TTI.syncImports=async function(){const result=await this.request('/imports');this.imported=new Map(result.features.map(f=>[f.id,f]));this.importNames=new Map(result.imports.filter(i=>i.active).map(i=>[i.id,i.label]));};
TTI.applyImportedPoint=function(f,p){const meta=this.imported?.get(f.id);if(!meta)return;f.importId=meta.importId;f.description=meta.description;f.deleted=Boolean(p.deleted)||!meta.active;if(p.category==='TTI (1)/Importate/'+meta.importId)f.style=meta.style;};
TTI.loadHistory=async function(){this.history=(await this.request('/history')).history;this.updateUndo?.();};
TTI.undoOperation=async function(event){if(this.busy)return;if(!confirm('Anulezi pentru toți utilizatorii: '+event.title+'?'))return;this.busy=true;this.updateUndo();try{await this.request('/history/'+event.id+'/undo',{method:'POST'});this.cancelCableSelection();this.cancelPointCreation?.();await this.refresh();selected=null;$('details').hidden=true;}catch(e){alert(e.message);await this.loadHistory().catch(()=>{});}finally{this.busy=false;this.updateUndo();}};
TTI.setupImports=function(){
 const input=el('input');input.type='file';input.accept='.kmz';input.hidden=true;input.setAttribute('aria-label','Fișier KMZ');
 const button=el('button','↑ Încarcă KMZ','add-point'),undo=el('button','↶ Undo','add-point'),history=el('button','Istoric comun','deleted-points');
 $('sidebar').insertBefore(button,$('sidebar').firstChild);button.after(undo,input);$('sidebar').insertBefore(history,$('sidebar').querySelector('footer'));
 this.updateUndo=()=>{document.querySelectorAll('#sidebar .add-point').forEach(n=>n.disabled=this.busy);undo.disabled=this.busy||!this.history?.some(e=>!e.undone_at);button.disabled=history.disabled=this.busy;};this.updateUndo();
 undo.onclick=()=>{const event=this.history?.find(e=>!e.undone_at);if(event)this.undoOperation(event);};button.onclick=()=>input.click();
 history.onclick=async()=>{try{await this.loadHistory();this.cancelCableSelection();const content=$('detail-content');content.replaceChildren(el('h2','Istoric comun','detail-title'),el('p','Ultimele 200 de importuri și mutări. Datele sunt afișate în ora României.'));selected=null;$('details').hidden=false;for(const event of this.history){const row=el('article',undefined,'observation'),date=new Intl.DateTimeFormat('ro-RO',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Bucharest'}).format(new Date(event.created_at.replace(' ','T')+'Z'));row.append(el('strong',event.title),el('p',date));const revert=el('button',event.undone_at?'Anulată':'Undo');revert.disabled=Boolean(event.undone_at);revert.onclick=()=>this.undoOperation(event);row.append(revert);content.append(row);}if(!this.history.length)content.append(el('p','Nu există încă importuri sau mutări în istoric.'));}catch(e){alert(e.message);}};
 const uploadPhotos=async(plan,message)=>{let failed=0;for(let i=0;i<plan.photos.length;i++){const photo=plan.photos[i];if(photo.uploaded)continue;message.textContent=`Fotografii: ${i+1} / ${plan.photos.length}…`;try{const bytes=await photo.entry.read();await this.request('/points/'+photo.pointId+'/photos?uploadId='+photo.id,{method:'POST',headers:{'Content-Type':/\.png$/i.test(photo.entry.name)?'image/png':/\.webp$/i.test(photo.entry.name)?'image/webp':'image/jpeg'},body:bytes});photo.uploaded=true;}catch(e){failed++;photo.error=e.message;}}return failed;};
 input.onchange=async()=>{const file=input.files[0];if(!file||this.busy)return;this.busy=true;this.updateUndo();this.cancelCableSelection();this.cancelPointCreation?.();selected=null;$('details').hidden=false;const content=$('detail-content'),message=el('p','Citesc arhiva KMZ…','save-status');message.setAttribute('role','status');content.replaceChildren(el('h2','Import KMZ','detail-title'),message);let plan;
 try{plan=await KMZ.parse(file);message.textContent=`Salvez ${plan.features.length} elemente…`;const payload=JSON.stringify({id:plan.id,label:plan.label,features:plan.features});if(new Blob([payload]).size>12*1024*1024)throw Error('Importul conține prea multe simboluri. Împarte KMZ-ul în fișiere mai mici.');await this.request('/imports',{method:'POST',headers:{'Content-Type':'application/json'},body:payload});const failed=await uploadPhotos(plan,message);await this.refresh();for(const key of this.importNames.keys())enabled.set('TTI (1)/Importate/'+key,true);render();const bounds=L.latLngBounds([]);for(const f of this.all.filter(f=>f.importId===plan.id)){if(f.type==='Point')bounds.extend(f.coordinates);else f.coordinates.forEach(p=>bounds.extend(p));}if(bounds.isValid())map.fitBounds(bounds,{padding:[50,70]});
 message.textContent=`Importat: ${plan.features.filter(f=>f.type==='Point').length} puncte, ${plan.features.filter(f=>f.type==='LineString').length} cabluri, ${plan.photos.filter(p=>p.uploaded).length} fotografii. Mută elementele din grupul Importate în layerele dorite.`+(plan.unsupported?' Geometrii nesuportate omise: '+plan.unsupported+'.':'');
 if(failed){message.textContent+=' Fotografii neîncărcate: '+failed+'.';const retry=el('button','Reîncearcă fotografiile');retry.onclick=async()=>{if(this.busy)return;this.busy=true;retry.disabled=true;try{const remaining=await uploadPhotos(plan,message);await this.refresh();message.textContent=remaining?'Mai sunt '+remaining+' fotografii neîncărcate.':'Toate fotografiile sunt încărcate.';}finally{this.busy=false;retry.disabled=false;this.updateUndo();}};content.append(retry);}
 }catch(e){message.textContent='Importul nu s-a încheiat: '+e.message;if(plan)message.textContent+=' Verifică grupul Importate și istoricul înainte de a reîncărca fișierul.';}finally{this.busy=false;this.updateUndo();input.value='';}
 };
};
